import json,re,html
exec(open('tools.py').read());exec(open('reality.py').read())
BASE="https://nurseaitools.com"
HIP={"deepscribe","nabla","navina","caregility","clinicalkey","lyrebird","tali.ai","sully","getfreed","hippocratic","care.coach","heidihealth","hyro","suki","artisight","andorhealth"}
CATS=[A,H,C,E,S,P,G]
def slug(s): return re.sub(r'[^a-z0-9]+','-',s.lower()).strip('-')
e=html.escape
tools=[]
for n,v,u,c,d,x in T:
    h=("Vendor website mentions HIPAA (checked Oct 15, 2026). BAA availability not confirmed here; ask the vendor." if any(k in u for k in HIP)
       else "Consumer version: do not enter patient information (PHI). Enterprise/BAA terms vary; check with your organization." if c==G
       else "Not publicly stated on vendor homepage; verify with vendor.")
    hs=("Mentions HIPAA" if any(k in u for k in HIP) else "Not for patient info" if c in (G,E) else "Unknown")
    bf,fit=R[n]
    tools.append(dict(built=bf,hstat=hs,fit=fit,slug=slug(n),name=n,vendor=v,url=u,category=c,what=d,ehr=x or "Not publicly listed; check with vendor",hipaa=h))
CSS="""*{box-sizing:border-box}body{margin:0;font-family:-apple-system,Segoe UI,Roboto,sans-serif;color:#1b2a3a;background:#f6f9fb;line-height:1.55}
a{color:#0b6e8a}header{background:#fff;border-bottom:1px solid #dfe7ec}nav,main,footer{max-width:1040px;margin:0 auto;padding:16px 20px}
nav{display:flex;justify-content:space-between;align-items:center}nav b{font-size:20px;color:#0b4f63}nav b span{color:#14a1a1}nav a{margin-left:16px;text-decoration:none}
.hero{padding:28px 0 8px}.hero h1{margin:0 0 6px;font-size:30px}.muted{color:#5b6b78}input,select,textarea{font:inherit;padding:10px 12px;border:1px solid #c8d4dc;border-radius:8px;width:100%}
.chips{display:flex;flex-wrap:wrap;gap:8px;margin:12px 0}.chip{border:1px solid #c8d4dc;background:#fff;border-radius:999px;padding:6px 12px;cursor:pointer;font-size:14px}.chip.on{background:#0b6e8a;color:#fff;border-color:#0b6e8a}
.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(300px,1fr));gap:14px}.card{background:#fff;border:1px solid #dfe7ec;border-radius:12px;padding:16px;text-decoration:none;color:inherit;display:block}.card:hover{border-color:#0b6e8a}
.tag{display:inline-block;font-size:12px;background:#e6f4f6;color:#0b4f63;border-radius:6px;padding:2px 8px}.rc{background:#f2f8fa;border:1px solid #cfe3ea;border-radius:10px;padding:12px 14px;margin:12px 0}.rc table{border-collapse:collapse;margin:6px 0}.rc td{padding:3px 14px 3px 0}.rc td:first-child{color:#5b6b78}.pend{font-size:12px;background:#fff6e0;color:#7a5a00;border-radius:6px;padding:2px 8px}
.box{background:#fff;border:1px solid #dfe7ec;border-radius:12px;padding:20px;margin:16px 0}dt{font-weight:600;margin-top:10px}dd{margin:2px 0 0}button{background:#0b6e8a;color:#fff;border:0;border-radius:8px;padding:10px 18px;font:inherit;cursor:pointer}
form>*{margin:6px 0}.row{display:flex;gap:8px}.row input{flex:1}footer{font-size:13px;color:#5b6b78}"""
NEWS="""<div class=box><h3 style=margin-top:0>Get the weekly “AI at the bedside” note</h3><p class=muted>New tools, rollouts, and what nurses are saying. No spam.</p>
<form class="row ajax" action="/api/subscribe"><input type=email name=email required placeholder="you@example.com"><input name=hp style=display:none tabindex=-1><button>Subscribe</button></form><p class=msg></p></div>"""
JS="""<script>document.querySelectorAll('form.ajax').forEach(f=>f.onsubmit=async e=>{e.preventDefault();const m=f.parentNode.querySelector('.msg');const r=await fetch(f.action,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(Object.fromEntries(new FormData(f)))});const j=await r.json().catch(()=>({}));m.textContent=r.ok?(j.message||'Thanks!'):(j.error||'Something went wrong.');if(r.ok)f.reset()})</script>"""
def page(title,desc,body,path):
    return f"""<!doctype html><html lang=en><head><meta charset=utf-8><meta name=viewport content="width=device-width,initial-scale=1"><title>{e(title)}</title><meta name=description content="{e(desc)}"><link rel=canonical href="{BASE}{path}"><meta property=og:title content="{e(title)}"><meta property=og:description content="{e(desc)}"><meta property=og:type content=website><meta property=og:url content="{BASE}{path}"><style>{CSS}</style></head><body><header><nav><a href="/" style="margin:0;text-decoration:none"><b>Nurse<span>AI</span>Tools</b></a><div><a href="/">Directory</a><a href="/submit">Submit a tool</a><a href="/about">About</a></div></nav></header><main>{body}</main><footer>© 2026 Nurse AI Tools · Independent directory, not affiliated with listed vendors · Not medical advice. Always follow your facility's policies.</footer>{JS}</body></html>"""
P_={}
cards="".join(f'<a class=card href="/tools/{t["slug"]}" data-c="{e(t["category"])}" data-n="{int(t["built"]=="Nurses")}" data-h="{int(t["hstat"] in ("Mentions HIPAA","BAA offered per vendor"))}" data-s="{e((t["name"]+" "+t["vendor"]+" "+t["what"]).lower())}"><span class=tag>{e(t["category"])}</span><h3 style="margin:8px 0 2px">{e(t["name"])}</h3><div class=muted style=font-size:14px>{e(t["vendor"])}</div><p style="font-size:14px;margin:8px 0">{e(t["what"])}</p><span class=pend>Built for: {e(t["built"])}</span> <span class=pend>{e(t["hstat"])}</span> <span class=pend>{e(t["fit"])}</span></a>' for t in tools)
chips='<button class="chip on" data-c="">All</button>'+"".join(f'<button class=chip data-c="{e(c)}">{e(c)}</button>' for c in CATS)
home=f"""<section class=hero><h1>AI tools for nurses, reviewed by a nurse</h1><p style="font-size:18px">Most clinical AI is built for physicians. Very few tools are made for bedside nurses yet. We track the ones that are, and tell you what&#39;s safe to use.</p><p class=muted>An independent directory of {len(tools)} AI tools nurses actually run into: ambient charting, handoff, decision support, NCLEX prep, staffing and more. Curated by a critical care RN.</p></section>
<input id=q placeholder="Search tools, vendors, or tasks (e.g. flowsheet, sepsis, NCLEX)"><div class=chips>{chips}</div><div class=chips><label class=chip><input type=checkbox id=fn style="width:auto"> Built for nurses</label><label class=chip><input type=checkbox id=fh style="width:auto"> HIPAA-ready</label></div><p class=muted id=count></p><div class=grid id=g>{cards}</div>{NEWS}
<script>let c='';const q=document.getElementById('q'),cs=[...document.querySelectorAll('.card')];function f(){{const s=q.value.toLowerCase();let n=0;cs.forEach(x=>{{const ok=(!c||x.dataset.c==c)&&x.dataset.s.includes(s)&&(!fn.checked||x.dataset.n=='1')&&(!fh.checked||x.dataset.h=='1');x.style.display=ok?'':'none';n+=ok}});document.getElementById('count').textContent=n+' tools'}}q.oninput=f;fn.onchange=f;fh.onchange=f;document.querySelectorAll('.chip').forEach(b=>b.onclick=()=>{{document.querySelectorAll('.chip').forEach(x=>x.classList.remove('on'));b.classList.add('on');c=b.dataset.c;f()}});f()</script>"""
P_["/"]=page("Nurse AI Tools: AI tools for nurses, curated by a critical care RN","Independent directory of AI tools for nurses: ambient documentation, handoff, clinical decision support, NCLEX prep, scheduling and patient communication.",home,"/")
for t in tools:
    b=f"""<p><a href="/">← All tools</a></p><div class=box><span class=tag>{e(t["category"])}</span><h1 style="margin:8px 0 0">{e(t["name"])}</h1><p class=muted>by {e(t["vendor"])}</p><div class=rc><b>RN reality check</b><table><tr><td>Built for</td><td>{e(t["built"])}</td></tr><tr><td>HIPAA status</td><td>{e(t["hstat"])}</td></tr><tr><td>Bedside fit</td><td>{e(t["fit"])}</td></tr></table><div class=muted style=font-size:12px>From vendor or public info only. "Unknown" means we could not verify it.</div></div>
<dl><dt>What it does for nurses</dt><dd>{e(t["what"])}</dd><dt>Category</dt><dd>{e(t["category"])}</dd><dt>Vendor</dt><dd>{e(t["vendor"])}</dd><dt>Official site</dt><dd><a href="{e(t["url"])}" rel="nofollow noopener" target=_blank>{e(t["url"])}</a></dd><dt>EHR integrations</dt><dd>{e(t["ehr"])}</dd><dt>HIPAA / BAA status</dt><dd>{e(t["hipaa"])}</dd></dl>
<p class=muted style=font-size:13px>Listing info is compiled from the vendor's public website and may change. Vendors can <a href="/submit">submit corrections</a>.</p></div>{NEWS}"""
    P_["/tools/"+t["slug"]]=page(f'{t["name"]} for nurses: features, EHR integrations, HIPAA | Nurse AI Tools',f'{t["name"]} by {t["vendor"]}: {t["what"]}'[:155],b,"/tools/"+t["slug"])
sub=f"""<div class=box><h1 style=margin-top:0>Submit a tool</h1><p class=muted>Know an AI tool nurses use? Vendors welcome too. Every submission is reviewed before listing.</p>
<form class=ajax action="/api/submit"><input name=name required placeholder="Tool name"><input name=url type=url required placeholder="Official website (https://…)"><select name=category>{"".join(f"<option>{e(c)}</option>" for c in CATS)}</select><textarea name=notes rows=4 placeholder="What does it do for nurses? EHR integrations? HIPAA/BAA?"></textarea><input name=email type=email placeholder="Your email (optional)"><input name=hp style=display:none tabindex=-1><button>Submit</button></form><p class=msg></p></div>"""
P_["/submit"]=page("Submit an AI tool for nurses | Nurse AI Tools","Suggest an AI tool for nurses to be reviewed and listed in the Nurse AI Tools directory.",sub,"/submit")
ab="""<div class=box><h1 style=margin-top:0>About</h1><p>Nurse AI Tools is curated by a registered nurse with 14 years of critical care experience who builds with AI on the side.</p><p>Hospitals are rolling out ambient charting, AI handoffs and early-warning tools fast, and nurses are often the last to hear how they actually work on a real shift. This site aims to be the plain-spoken, nurse-first reference.</p><h3>How listings work</h3><ul><li>Facts (vendor, integrations, HIPAA/BAA statements) come from vendors' public websites and are labeled when unconfirmed.</li><li>Every tool gets an <b>RN reality check</b>: who it is built for, its HIPAA status, and whether it fits a bedside workflow. Each answer comes only from vendor or public information. If we cannot verify it, we say Unknown.</li><li>Listings are independent. Any future sponsored placements will be clearly labeled.</li></ul><p>Nothing here is medical advice. Never enter patient information into a tool your facility hasn't approved.</p></div>"""+NEWS
P_["/about"]=page("About Nurse AI Tools: curated by a critical care RN","Nurse AI Tools is an independent directory of AI tools for nurses, curated by a critical care registered nurse.",ab,"/about")
sm='<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+"".join(f"<url><loc>{BASE}{p}</loc><lastmod>2026-10-15</lastmod></url>" for p in P_)+"</urlset>"
json.dump(tools,open("tools.json","w"),indent=1)
W=open("worker.template.js").read().replace("__PAGES__",json.dumps(P_)).replace("__SITEMAP__",json.dumps(sm)).replace("__BASE__",BASE)
open("dist/worker.js","w").write(W); print(len(tools),"tools",len(P_),"pages",len(W),"bytes")
